let content = fs.readFileSync('lib/i18n.jsx', 'utf8');

missingKeys.forEach(key => {
  const t = translations[key];
  if(t) {
    const searchRegex = new RegExp(`\\n\\s+${key}:\\s*"[^"]*",`, "g");
    content = content.replace(searchRegex, (match, offset, string) => {
        if (offset < string.indexOf('  en: {')) {
            return `\n    ${key}: "${t}",`;
        }
        return match;
    });
  }
});

fs.writeFileSync('lib/i18n.jsx', content);
console.log('Translations updated successfully');
